# A year is a leap year if it divides by 4, but not by 100 unless it divides by 400.
Leap :: {}.{
    is_leap_year : U64 -> Bool
    is_leap_year = |year| {
        divisible_by = |n| year % n == 0
        divisible_by(4) and (!divisible_by(100) or divisible_by(400))
    }
}

